  Label Stat(TableLayoutPanel parent,string caption,string value,Color color){var card=new Card{Dock=DockStyle.Fill,Margin=new Padding(0,0,10,0),Padding=new Padding(16,10,16,10)};var top=Theme.Label(caption,8,Theme.Muted,true);top.Dock=DockStyle.Top;top.Height=22;var number=Theme.Label(value,24,color,true);number.Dock=DockStyle.Bottom;number.Height=42;card.Controls.Add(top);card.Controls.Add(number);parent.Controls.Add(card);return number;}
  InstalledApp Selected{get{return grid.SelectedRows.Count==0?null:grid.SelectedRows[0].Tag as InstalledApp;}}
  void Reload(){try{all=Catalog.Read();appCount.Text=all.Count.ToString();pubCount.Text=all.Select(a=>a.Publisher).Where(p=>!String.IsNullOrWhiteSpace(p)).Distinct(StringComparer.OrdinalIgnoreCase).Count().ToString();Filter();}catch(Exception ex){Error(ex);}}
  void Filter(){if(grid==null)return;grid.Rows.Clear();string query=search.Text.Trim();foreach(var app in all.Where(a=>(a.Name.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0||a.Publisher.IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0)&&(scope.SelectedIndex==0||(scope.SelectedIndex==1?a.Machine:!a.Machine)))){Bitmap icon;if(!icons.TryGetValue(app.Name,out icon)){icon=Theme.AppIcon(app,36);icons[app.Name]=icon;}int i=grid.Rows.Add(icon,app.Name,app.Publisher,app.Version);grid.Rows[i].Tag=app;}count.Text="Приложений: "+grid.Rows.Count+"   ·   Выберите программу из списка";Selection();}
  void Selection(){var app=Selected;remove.Enabled=app!=null;folder.Enabled=app!=null&&!String.IsNullOrEmpty(app.Location)&&Directory.Exists(app.Location);title.Text=app==null?"Выберите приложение":app.Name;details.Text=app==null?"Найдите программу в списке выше.":(app.Machine?"Для всех пользователей":"В вашем профиле")+"  ·  "+app.Version+"\n"+(String.IsNullOrEmpty(app.Location)?"Путь установки не указан":app.Location);}
  void UpdatePending(){scan.Enabled=true;stepText.Text=pending==null?"Удаление → поиск остатков → очистка":"Ожидаем завершения: "+pending.Name;}
  void OpenFolder(){try{if(Selected!=null&&Directory.Exists(Selected.Location))Process.Start(new ProcessStartInfo("explorer.exe","\""+Selected.Location+"\""){UseShellExecute=true});}catch(Exception ex){Error(ex);}}
  void UninstallSelected(){var app=Selected;if(app==null)return;try{
   if(pending!=null&&Scanner.Installed(pending,Catalog.Read())){MessageBox.Show(this,"Сначала завершите уже запущенное удаление: "+pending.Name,"Удаление выполняется");return;}
   var start=Catalog.Uninstall(app);
   if(MessageBox.Show(this,"Удалить «"+app.Name+"»?\n\n1. Пройдите стандартный мастер удаления.\n2. AppShelf затем найдёт остатки в реестре и папках.\n3. Просмотрите список и нажмите «Очистить».\n\nРезервная копия реестра создаётся автоматически.","Удалить начисто",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
   // Persist identity before the uninstaller removes its registration.
   Store.Write(PendingFile,app);Process.Start(start);pending=app;absentTicks=0;timer.Start();UpdatePending();status.Text="Завершите мастер удаления. AppShelf продолжит автоматически.";
  }catch(System.ComponentModel.Win32Exception ex){if(ex.NativeErrorCode==1223){status.Text="Удаление отменено.";try{File.Delete(PendingFile);}catch{}}else Error(ex);}catch(Exception ex){Error(ex);}}
  void Poll(){if(pending==null||scanning)return;try{if(!Scanner.Installed(pending,Catalog.Read())){absentTicks++;if(absentTicks>=3){timer.Stop();StartScan(pending);}}else absentTicks=0;}catch{}}
  void PreviewSelected(){if(Selected!=null)StartScan(Selected);else MessageBox.Show(this,"Выберите программу для проверки остатков.","Поиск остатков");}
  void StartScan(InstalledApp app){if(scanning)return;scanning=true;try{using(var dialog=new CleanupForm(app))dialog.ShowDialog(this);Reload();if(pending!=null&&!Scanner.Installed(pending,all)){stepText.Text="Удалено: "+pending.Name+" · можно повторить поиск остатков";}absentTicks=0;}finally{scanning=false;}}
  void OpenData(){try{Directory.CreateDirectory(Store.Home);Process.Start(new ProcessStartInfo("explorer.exe","\""+Store.Home+"\""){UseShellExecute=true});}catch(Exception ex){Error(ex);}}
  void RestoreDialog(){using(var backups=new BackupsForm())backups.ShowDialog(this);}
  void Error(Exception ex){MessageBox.Show(this,ex.Message,"AppShelf",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
 }
 public class CleanupForm:Form {
  InstalledApp app;ScanResult result;DataGridView grid;Label summary,step,status;SoftButton clean,recommended,all,again;bool preview;ProgressBar progress;bool busy;
  public CleanupForm(InstalledApp selected){app=selected;Theme.Apply(this);Text="Очистка · "+app.Name;Size=new Size(1120,760);MinimumSize=new Size(1000,650);StartPosition=FormStartPosition.CenterParent;
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=7,Padding=new Padding(26)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Absolute,40));root.RowStyles.Add(new RowStyle(SizeType.Absolute,66));root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,36));root.RowStyles.Add(new RowStyle(SizeType.Absolute,58));Controls.Add(root);
   var title=Theme.Label("Уберём оставшиеся следы",25,Theme.Text,true);title.Dock=DockStyle.Fill;root.Controls.Add(title);step=Theme.Label("01  Удаление   →   02  Поиск остатков   →   03  Очистка",10,Theme.Accent,true);step.Dock=DockStyle.Fill;root.Controls.Add(step);
   summary=Theme.Label("Сканируем реестр и папки для «"+app.Name+"»…",11,Theme.Text,false);summary.Dock=DockStyle.Fill;root.Controls.Add(summary);
   var tools=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};recommended=new SoftButton("Точные совпадения",false){Width=190};all=new SoftButton("Снять всё",false){Width=120};again=new SoftButton("Повторить поиск",false){Width=145};tools.Controls.Add(recommended);tools.Controls.Add(all);tools.Controls.Add(again);root.Controls.Add(tools);
   grid=new DataGridView();Theme.Grid(grid);grid.ReadOnly=false;grid.RowTemplate.Height=48;grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="Checked",HeaderText="",Width=40});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Kind",HeaderText="ТИП",Width=90,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Path",HeaderText="РАЗДЕЛ / ПАПКА",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill,FillWeight=65,ReadOnly=true});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Reason",HeaderText="ПОЧЕМУ НАЙДЕНО",AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill,FillWeight=35,ReadOnly=true});grid.CellContentClick+=(s,e)=>{if(e.ColumnIndex==0)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=(s,e)=>UpdateCount();grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex>=0)ShowFinding(grid.Rows[e.RowIndex].Tag as Finding);};root.Controls.Add(grid);
   status=Theme.Label("",9,Theme.Muted,false);status.Dock=DockStyle.Fill;root.Controls.Add(status);
   var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};clean=new SoftButton("Очистить выбранное",true){Width=230};var close=new SoftButton("Готово",false){Width=120};footer.Controls.Add(clean);footer.Controls.Add(close);progress=new ProgressBar{Style=ProgressBarStyle.Marquee,Width=210,Height=14,Visible=false,Margin=new Padding(10,14,10,0)};footer.Controls.Add(progress);root.Controls.Add(footer);
   close.Click+=(s,e)=>Close();recommended.Click+=(s,e)=>{foreach(DataGridViewRow row in grid.Rows)row.Cells[0].Value=((Finding)row.Tag).Recommended;UpdateCount();};all.Click+=(s,e)=>{foreach(DataGridViewRow row in grid.Rows)row.Cells[0].Value=false;UpdateCount();};again.Click+=(s,e)=>ScanAsync();clean.Click+=(s,e)=>CleanAsync();Shown+=(s,e)=>ScanAsync();FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};
  }
  void SetBusy(bool value){busy=value;progress.Visible=value;again.Enabled=!value;recommended.Enabled=!value;all.Enabled=!value;grid.Enabled=!value;clean.Enabled=!value&&!preview&&grid.Rows.Cast<DataGridViewRow>().Any(r=>Convert.ToBoolean(r.Cells[0].Value));}
  async void ScanAsync(){if(busy)return;SetBusy(true);summary.Text="Ищем следы «"+app.Name+"» в реестре и папках…";
   try{result=await Task.Run(()=>Scanner.Scan(app));preview=Scanner.Installed(app,Catalog.Read());grid.Rows.Clear();foreach(var f in result.Items){int i=grid.Rows.Add(f.Recommended,!f.File?(f.WholeKey?"Реестр":"Параметр"):"Папка",f.Display,f.Reason);grid.Rows[i].Tag=f;}
    summary.Text=preview?"Предпросмотр: программа ещё установлена. Очистка откроется после её удаления.":"«"+app.Name+"» удалена. Проверьте найденные остатки перед очисткой.";
    step.Text=preview?"Предпросмотр остатков · удаление ещё не завершено":"01  Удалено   →   02  Остатки найдены   →   03  Очистить";
    if(result.Skipped.Count>0){string file=Path.Combine(Store.Home,"scan-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".txt");Directory.CreateDirectory(Store.Home);File.WriteAllLines(file,result.Skipped, System.Text.Encoding.UTF8);summary.Text+="\nЧасть разделов пропущена: "+result.Skipped.Count+". Подробности в журнале.";}
   }catch(Exception ex){summary.Text="Не удалось завершить сканирование: "+ex.Message;}finally{SetBusy(false);UpdateCount();}}
  List<Finding> Selected(){return grid.Rows.Cast<DataGridViewRow>().Where(r=>Convert.ToBoolean(r.Cells[0].Value)).Select(r=>(Finding)r.Tag).Where(f=>f!=null).ToList();}
  void UpdateCount(){if(grid==null||clean==null)return;var selected=Selected();status.Text="Найдено: "+grid.Rows.Count+"     ·     Выбрано: "+selected.Count+"     ·     Папки с личными данными выбираются вручную";clean.Text=selected.Count==0?"Нечего очищать":"Очистить · "+selected.Count;clean.Enabled=!busy&&!preview&&selected.Count>0;}
  async void CleanAsync(){if(busy||preview)return;grid.EndEdit();var selected=Selected();if(selected.Count==0)return;
   if(MessageBox.Show(this,"Очистить выбранные остатки «"+app.Name+"»?\n\nЗаписей реестра: "+selected.Count(f=>!f.File)+"\nПапок: "+selected.Count(f=>f.File)+"\n\nКопия реестра будет сохранена до очистки. Папки будут отправлены в корзину Windows.\n\nЕсли в найденных разделах есть нужные настройки, снимите с них отметки.","Подтверждение очистки",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;
   SetBusy(true);try{
    var job=new CleanupJob{App=app,UserSid=Store.Sid,Selected=selected};CleanupReport report;
    if(!Store.Admin&&selected.Any(f=>!f.File&&f.Hive==RegistryHive.LocalMachine)){
     string file=Path.Combine(Store.Home,"Jobs",Guid.NewGuid().ToString("N")+".xml");Store.Write(file,job);
     var child=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--cleanup \""+file+"\""){UseShellExecute=true,Verb="runas"});await Task.Run(()=>child.WaitForExit());
     string response=file+".result.xml";if(!File.Exists(response))throw new IOException("Очистка не завершилась. Повторите сканирование.");report=Store.Read<CleanupReport>(response);
    }else report=CleanupEngine.Clean(job);
    string message="Очищено: "+report.Done.Count+". Пропущено: "+report.Failed.Count+".\n\nКопия реестра: "+report.BackupFile;if(report.Failed.Count>0)message+="\n\n"+String.Join("\n",report.Failed.Take(6));MessageBox.Show(this,message,"Результат очистки",MessageBoxButtons.OK,report.Failed.Count==0?MessageBoxIcon.Information:MessageBoxIcon.Warning);
    step.Text="03  Готово · резервная копия сохранена";
   }catch(System.ComponentModel.Win32Exception ex){summary.Text=ex.NativeErrorCode==1223?"Запрос администратора отменён.":ex.Message;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Очистка не завершена",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{SetBusy(false);ScanAsync();}
  }
  void ShowFinding(Finding f){if(f==null)return;try{if(f.File){Process.Start(new ProcessStartInfo("explorer.exe","\""+f.Path+"\""){UseShellExecute=true});return;}
   using(var root=RegistryKey.OpenBaseKey(f.Hive,f.View))using(var key=root.OpenSubKey(f.Path)){var node=Snapshot.Capture(key,f.WholeKey?null:f.ValueName);var text=new System.Text.StringBuilder();text.AppendLine(f.Display);text.AppendLine(f.Reason);text.AppendLine();DumpNode(node,"",text);using(var viewer=new Form{Text="Содержимое раздела",Size=new Size(850,580),StartPosition=FormStartPosition.CenterParent}){var box=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Font=new Font("Consolas",10),Text=text.ToString(),BackColor=Theme.Card,ForeColor=Theme.Text};viewer.Controls.Add(box);viewer.ShowDialog(this);}}
   }catch(Exception ex){MessageBox.Show(this,ex.Message,"Просмотр");}}
  void DumpNode(NodeSnapshot node,string prefix,System.Text.StringBuilder text){text.AppendLine(prefix+"["+node.Name+"]");foreach(var v in node.Values)text.AppendLine(prefix+"  "+(v.Name.Length==0?"(По умолчанию)":v.Name)+" ["+v.Kind+"] = "+(v.Text??(v.Strings==null?(v.Bytes==null?v.Number.ToString():BitConverter.ToString(v.Bytes)):String.Join(" | ",v.Strings))));foreach(var child in node.Children)DumpNode(child,prefix+"  ",text);}
 }
}




